/** @returns {Vec3 | undefined} */
function findCorrectionVector(  /** @type {TransformerRuntimeApi} */ api,
  /** @type {Vec3} */  origin,
  /** @type {Vec3} */ rotation,
  /** @type {number} */ distance,
  /** @type {Rotation} */ entityRotation) {
  const up = api.getUpVector(entityRotation);
  let rightRotation = api.vec.rotateAroundAxis(rotation, up, 0.3);
  let leftRotation = api.vec.rotateAroundAxis(rotation, up, -0.3);

  let rightResult = api.raycast(origin, rightRotation, distance, { visualize: true });
  let leftResult = api.raycast(origin, leftRotation, distance, { visualize: true });
  let resultRotation = undefined;
  if (rightResult.hit && leftResult.hit) resultRotation = leftResult.distance > rightResult.distance ? leftRotation : rightRotation;
  else if (!rightResult.hit) resultRotation = rightRotation;
  else resultRotation = leftRotation;

  return api.vec.add(origin, api.vec.scale(api.vec.normalize(resultRotation), distance));


}

